mapper.select:
SELECT SQL_CALC_FOUND_ROWS pm.mk_id, pm.place_name, pm.subject, pm.contents, pm.tag_nm, pm.mk_type, pm.mk_status, pm.mk_price, pm.address, pm.longitude, pm.latitude, CASE WHEN (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id AND mb_id = #{mbId}) > 0 THEN 1 ELSE 0 END AS like_fl, (SELECT bf_fileurl FROM g5_board_file gbf INNER JOIN pet_market_file_mapping pmfm ON gbf.bo_table = 'pet_market' AND gbf.wr_id = pmfm.mk_fm_id WHERE pmfm.mk_id = pm.mk_id LIMIT 1) AS image_url, pm.create_ymd, (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id) AS like_cnt FROM pet_market pm INNER JOIN g5_member gm ON pm.mb_id = gm.mb_id WHERE pm.del_fl = 0 AND fn_block_member(#{mbId},pm.mb_id) < 1
AND ((pm.subject LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pm.contents LIKE CONCAT('%', #{searchKeyword}, '%')))
AND pm.mkType = #{mkType}
ORDER BY ST_Distance_Sphere( POINT(#{longitude}, #{latitude}), POINT(CAST(pm.longitude AS DECIMAL(15,12)), CAST(pm.latitude AS DECIMAL(15,12))) ), pm.mk_status
ORDER BY pm.create_ymd, pm.mk_status DESC
LIMIT #{pageNo}, #{pageSize};

mapper.insert:
INSERT INTO pet_market_file_mapping (
    mk_id,
    mb_id
) VALUES (
    #{mkId},
    #{mbId}
);

INSERT INTO pet_market_purchase (
    mk_id,
    sender_mb_id,
    receiver_mb_id,
    contents,
    purchase_status
) VALUES (
    #{mkId},
    #{senderMbId},
    #{receiverMbId},
    #{contents},
    #{purchaseStatus}
);

mapper.select:
SELECT SQL_CALC_FOUND_ROWS pm.mk_id, pm.place_name, pm.subject, pm.contents, pm.tag_nm, pm.mk_type, pm.mk_status, pm.mk_price, pm.address, pm.longitude, pm.latitude, CASE WHEN (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id AND mb_id = #{mbId}) > 0 THEN 1 ELSE 0 END AS like_fl, (SELECT bf_fileurl FROM g5_board_file gbf INNER JOIN pet_market_file_mapping pmfm ON gbf.bo_table = 'pet_market' AND gbf.wr_id = pmfm.mk_fm_id WHERE pmfm.mk_id = pm.mk_id LIMIT 1) AS image_url, pm.create_ymd, (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id) AS like_cnt FROM pet_market pm WHERE pm.del_fl = 0 AND pm.mb_id = #{receiverMbId} AND fn_block_member(#{mbId},pm.mb_id) < 1
AND pm.mk_id NOT IN (#{mkId})
AND pm.mk_status = #{mkStatus}
ORDER BY pm.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

mapper.insert:
INSERT INTO pet_market_like_mapping (
    mk_id,
    mb_id
) VALUES (
    #{mkId},
