);

mapper.select:
SELECT SQL_CALC_FOUND_ROWS pm.mk_id, pm.place_name, pm.subject, pm.contents, pm.tag_nm, pm.mk_type, pm.mk_status, pm.mk_price, pm.address, pm.longitude, pm.latitude, CASE WHEN (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id AND mb_id = #{mbId}) > 0 THEN 1 ELSE 0 END AS like_fl, (SELECT bf_fileurl FROM g5_board_file gbf INNER JOIN pet_market_file_mapping pmfm ON gbf.bo_table = 'pet_market' AND gbf.wr_id = pmfm.mk_fm_id WHERE pmfm.mk_id = pm.mk_id LIMIT 1) AS image_url, pm.create_ymd, (SELECT COUNT(*) FROM pet_market_like_mapping WHERE mk_id = pm.mk_id) AS like_cnt FROM pet_market pm INNER JOIN g5_member gm ON pm.mb_id = gm.mb_id LEFT JOIN pet_market_like_mapping pmlm ON pmlm.mk_id = pm.mk_id AND pmlm.mb_id = #{mbId} LEFT JOIN pet_market_purchase pmp ON pmp.mk_id = pm.mk_id LEFT JOIN g5_board_file gbf ON gbf.bo_table = 'user_profile' AND gm.mb_no = gbf.wr_id WHERE pm.del_fl = 0
AND pmlm.mb_id = #{mbId}
AND pmp.sender_mb_id = #{mbId}
AND pm.mb_id = #{mbId}
AND pm.mk_status = #{mkStatus}
ORDER BY pm.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

