mapper.select:
SELECT SQL_CALC_FOUND_ROWS gm.mb_nick, vml.level, IFNULL(pmlr.level_type_nm, 'Lv.0') AS level_type_nm, vml.level_nm, pmmh.subject, pmmh.contents, gbf.bf_fileurl AS user_profile_url, pmmh.use_mapping_id, pmmh.mb_id FROM pet_member_manage_history pmmh INNER JOIN g5_member gm ON pmmh.target_mb_id = gm.mb_id INNER JOIN v_member_level vml ON gm.mb_id = vml.mb_id LEFT JOIN pet_member_level_role pmlr ON vml.level = pmlr.level AND vml.del_fl = pmlr.del_fl LEFT JOIN g5_board_file gbf ON gbf.bo_table = 'user_profile' AND gm.mb_no = gbf.wr_id WHERE pmmh.del_fl = 0
AND pmmh.use_type = #{useType}
AND pmmh.mb_id = #{mbId} LIMIT #{pageNo}, #{pageSize};
